  '\n// ------------------------------------------------------------------------------------------------ recorded streams\n',
  '\n'
  '// everything the fast pixel loop reads of one triangle (captured when the triangle is set up, so a queued job does not '
  'depend on\n'
  '// later state calls; the texel pointer stays valid because every texture upload / deletion runs the queue first)\n'
  'struct GlRaster::FastJob {\n'
  '  uint16_t *fb;\n'
  '  int fbw, miny, maxy, minx, maxx;\n'
  '  int64_t A[3], B[3], X[3], Y[3];\n'
  '  bool inc[3];\n'
  '  double s0, s1, s2, t0, t1, t2, r0, r1, r2, g0, g1, g2, b0, b1, b2;\n'
  '  double div_st, arA, inv_st, inv_a, twd, thd;\n'
  '  const uint8_t *td;\n'
  '  uint32_t tw, th;\n'
  '  int bpp, dith;\n'
  '  bool linear, modulate, blend, white, approx, sloppy;\n'
  '  bool wctl;   // worker_ctl (negative control)\n'
  '};\n'
  '\n'
  '// The pixel-loop workers (set_threads): a ring of jobs written in order by the thread that sets the triangles up; worker k\n'
  '// rasterises, for every job in order, only the rows whose 4-row band (y >> 2) is k modulo the worker count. Each pixel then '
  'sees\n'
  '// the same writes in the same order as with one thread, so the frame is the same; the counters are summed by finish().\n'
  'struct GlRaster::Pool {\n'
  '  static constexpr uint64_t kCap = 4096;\n'
  '  std::vector<FastJob> ring;\n'
  '  std::atomic<uint64_t> published{0};\n'
  '  std::unique_ptr<std::atomic<uint64_t>[]> done;\n'
  '  std::vector<std::array<int64_t, 3>> counters;   // per worker: drawn, blended, fast (written by the worker before done)\n'
  '  std::mutex m;\n'
  '  std::condition_variable cv_work, cv_done;\n'
  '  bool stop = false;\n'
  '  int parts = 0;\n'
  '  std::vector<std::thread> threads;\n'
  '\n'
  '  uint64_t min_done() const {\n'
  '    uint64_t lo = ~0ull;\n'
  '    for (int k = 0; k < parts; ++k) lo = std::min(lo, done[k].load());\n'
  '    return lo;\n'
  '  }\n'
  '  void work(int k) {\n'
  '    uint64_t i = 0;\n'
  '    for (;;) {\n'
  '      const uint64_t n = published.load();\n'
  '      if (i < n) {\n'
  '        int64_t *c = counters[static_cast<size_t>(k)].data();\n'
  '        for (; i < n; ++i) fast_rows_(ring[i % kCap], k, parts, c);\n'
  '        done[k].store(i);\n'
  '        std::lock_guard<std::mutex> lk(m);\n'
  '        cv_done.notify_all();\n'
  '        continue;\n'
  '      }\n'
  '      std::unique_lock<std::mutex> lk(m);\n'
  '      cv_work.wait(lk, [&] { return stop || published.load() > i; });\n'
  '      if (stop && published.load() <= i) return;\n'
  '    }\n'
  '  }\n'
  '};\n'
  '\n'
  'GlRaster::~GlRaster() { set_threads(1); }\n'
  '\n'
  'void GlRaster::set_threads(int n) {\n'
  '  finish();\n'
  '  if (pool_) {\n'
  '    {\n'
  '      std::lock_guard<std::mutex> lk(pool_->m);\n'
  '      pool_->stop = true;\n'
  '    }\n'
  '    pool_->cv_work.notify_all();\n'
  '    for (std::thread &t : pool_->threads) t.join();\n'
  '    pool_.reset();\n'
  '  }\n'
  '  if (n <= 1) return;\n'
  '  pool_ = std::make_unique<Pool>();\n'
  '  Pool &p = *pool_;\n'
  '  p.ring.resize(Pool::kCap);\n'
  '  p.parts = n;\n'
  '  p.done = std::make_unique<std::atomic<uint64_t>[]>(static_cast<size_t>(n));\n'
  '  for (int k = 0; k < n; ++k) p.done[k].store(0);\n'
  '  p.counters.assign(static_cast<size_t>(n), {0, 0, 0});\n'
  '#ifdef _WIN32\n'
  '  const int prio = GetThreadPriority(GetCurrentThread());   // the workers run at the priority of the thread that feeds them\n'
  '#endif\n'
  '  for (int k = 0; k < n; ++k) {\n'
  '    p.threads.emplace_back([&p, k] { p.work(k); });\n'
  '#ifdef _WIN32\n'
  '    if (prio != THREAD_PRIORITY_ERROR_RETURN) SetThreadPriority(p.threads.back().native_handle(), prio);\n'
  '#endif\n'
  '  }\n'
  '}\n'
  '\n'
  'int GlRaster::threads() const { return pool_ ? pool_->parts : 1; }\n'
  '\n'
  'void GlRaster::finish() {\n'
  '  if (!pool_) return;\n'
  '  Pool &p = *pool_;\n'
  '  const uint64_t n = p.published.load();\n'
  '  {\n'
  '    std::unique_lock<std::mutex> lk(p.m);\n'
  '    p.cv_work.notify_all();\n'
  '    p.cv_done.wait(lk, [&] { return p.min_done() >= n; });\n'
  '  }\n'
  '  for (std::array<int64_t, 3> &c : p.counters) {\n'
  '    stats.drawn_px += c[0];\n'
  '    stats.blended_px += c[1];\n'
  '    stats.fast_px += c[2];\n'
  '    c = {0, 0, 0};\n'
  '  }\n'
  '}\n'
  '\n'
  'void GlRaster::queue_(const FastJob &j) {\n'
  '  Pool &p = *pool_;\n'
  '  const uint64_t n = p.published.load();\n'
  '  if (n - p.min_done() >= Pool::kCap) {\n'
  '    std::unique_lock<std::mutex> lk(p.m);\n'
  '    p.cv_work.notify_all();\n'
  '    p.cv_done.wait(lk, [&] { return n - p.min_done() < Pool::kCap; });\n'
  '  }\n'
  '  p.ring[n % Pool::kCap] = j;\n'
  '  p.published.store(n + 1);\n'
  '  if (((n + 1) & 15) == 0) {\n'
  '    std::lock_guard<std::mutex> lk(p.m);\n'
  '    p.cv_work.notify_all();\n'
  '  }\n'
  '}\n'
  '\n'
  '// The general loop of triangle() with every tune knob 0 (tune 11 aside) and keep_float_ off, computed faster to the same '
  'bits\n'
  '// (roadmap S3.10, log/roadmap/S3/10_notes.md section 2):\n'
  '//   - the setup vertices sx_ / sy_ are multiples of 2^-8 (nearbyint(256 v) / 256); while they and the pixel centres stay '
  'below\n'
  '//     2^14 in magnitude, every edge function of the general loop, (bx - ax) * (py - ay) - (by - ay) * (px - ax), is exact '
  'in\n'
  '//     double (differences of 23 significant bits, products of 46, their difference of 47), so it equals the int64 value in '
  'units\n'
  '//     of 2^-16 used here, and its sign and zero tests are the same. The attribute weights a0..a2 of the general loop are the '
  'same\n'
  '//     edge functions of the same vertices at the same centre (spx = px, spy = py with tunes 6 / 15 / 18 / 19 at 0), so they '
  'are\n'
  '//     these values converted back to double (exact below 2^53);\n'
  "//   - per row, each edge's inside test (w > 0, or w == 0 on an owning edge) is linear in the pixel column, so the covered "
  'pixels\n'
  "//     are the integer interval the three tests give (floor / ceil divisions), clipped to the general loop's bounding box;\n"
  '//   - floor, the repeat wrap, the dither offset and dst * 255 / 31 are the helpers and tables above.\n'
  '// The exact branch of the loop writes every other expression (texture coordinates, filtering, colours, modulation, '
  'blending,\n'
  '// quantisation) as the general loop does, in the same order. Returns false without writing when a precondition fails: the '
  'caller\n'
  '// then runs the general loop.\n'
  "// THE CHECKED RECIPROCAL PATH (fast_mode 1) computes a pixel first with the five divisions by the triangle's areas and the\n"
  '// three by 255 replaced by products with the reciprocals, and keeps that pixel only when it cannot differ from the exact '
  "branch's:\n"
  '//   - the numerators are the same doubles, so each quotient differs from the exact one by at most 1.5 * 2^-52 relative; with '
  'the\n'
  '//     texel coordinates u, v below 2^16 they differ by less than 1e-10, and so do the bilinear fractions ax, ay (fu - '
  'floor(fu) is\n'
  '//     exact). The texel indices are equal when the fraction is farther than kTexEps = 1e-9 from 0 and 1 (nearest: u - '
