  '// With workers (set_threads) the job is queued and rasterised by them; finish() waits for it.\n'
  '// port/test/test_gl_raster.py compares whole frames of the loops (fast_mode 0, 1, 2, workers) on the recorded streams.\n'
  'bool GlRaster::fast_triangle_(const Vtx *v0, const Vtx *v1, const Vtx *v2, double ar, const Tex &tex, bool linear, int minx,\n'
