  '    j.inc[i] = inc[i];\n'
  '  }\n'
  '  j.arA = std::fabs(edge(sx_[0], sy_[0], sx_[1], sy_[1], sx_[2], sy_[2]));\n'
  '  j.div_st = linear ? j.arA : ar;   // the general loop divides the texture coordinates by arA (linear) or ar (nearest)\n'
  '  j.linear = linear;\n'
  '  j.bpp = tex.fmt == kGlRgba ? 4 : 3;\n'
  '  j.td = tex.data.data();\n'
  '  j.tw = tex.w;\n'
  '  j.th = tex.h;\n'
  '  j.twd = static_cast<double>(tex.w);\n'
  '  j.thd = static_cast<double>(tex.h);\n'
  '  j.s0 = v0->s; j.s1 = v1->s; j.s2 = v2->s; j.t0 = v0->t; j.t1 = v1->t; j.t2 = v2->t;\n'
  '  j.r0 = v0->r; j.r1 = v1->r; j.r2 = v2->r; j.g0 = v0->g; j.g1 = v1->g; j.g2 = v2->g; j.b0 = v0->b; j.b1 = v1->b; j.b2 = '
  'v2->b;\n'
  '  // the checked reciprocal path (fast_mode 1; negative controls: 3 skips the boundary checks, 4 rounds the reciprocals to '
  'float)\n'
  '  j.sloppy = fast_mode == 3;\n'
  '  j.wctl = worker_ctl == 1;\n'
  '  bool approx = (fast_mode == 1 || fast_mode == 3 || fast_mode == 4) && j.div_st > 0 && j.div_st < 1e300 && j.arA > 0 &&\n'
  '                j.arA < 1e300;\n'
  '  for (const Vtx *p : {v0, v1, v2})\n'
  '    approx = approx && p->r >= 0 && p->r <= 1 && p->g >= 0 && p->g <= 1 && p->b >= 0 && p->b <= 1 && std::isfinite(p->s) &&\n'
  '             std::isfinite(p->t);\n'
  '  j.approx = approx;\n'
  '  j.inv_st = approx ? 1.0 / j.div_st : 0.0;\n'
  '  j.inv_a = approx ? 1.0 / j.arA : 0.0;\n'
  '  if (fast_mode == 4) {\n'
  '    j.inv_st = static_cast<float>(j.inv_st);\n'
  '    j.inv_a = static_cast<float>(j.inv_a);\n'
  '  }\n'
  '  if (pool_) {\n'
  '    queue_(j);\n'
  '  } else {\n'
  '    int64_t c[3] = {0, 0, 0};\n'
  '    fast_rows_(j, 0, 1, c);\n'
  '    stats.drawn_px += c[0];\n'
  '    stats.blended_px += c[1];\n'
  '    stats.fast_px += c[2];\n'
  '  }\n'
  '  return true;\n'
  '}\n'
  '\n'
  '// the rows y of job j with (y >> 2) % parts == part; c: drawn, blended and reciprocal-path pixel counts\n'
  'void GlRaster::fast_rows_(const FastJob &j, int part, int parts, int64_t *c) {\n'
  '  const FastTables &tb = fast_tables();\n'
  '  const double(*dith)[4] = tb.dither[j.dith];\n'
  '  constexpr double kUnit = 1.0 / 65536.0;\n'
  '  constexpr double kTexLim = 65536.0, kTexEps = 1e-9, kQuantEps = 1e-6, kInv255 = 1.0 / 255.0, k31of255 = 31.0 / 255.0;\n'
  '  const bool linear = j.linear, modulate = j.modulate, blend = j.blend, white = j.white, approx = j.approx, sloppy = '
  'j.sloppy;\n'
  '  const int bpp = j.bpp;\n'
  '  const uint8_t *td = j.td;\n'
  '  const uint32_t tw = j.tw, th = j.th;\n'
  '  const double twd = j.twd, thd = j.thd, div_st = j.div_st, arA = j.arA, inv_st = j.inv_st, inv_a = j.inv_a;\n'
  '  const double s0 = j.s0, s1 = j.s1, s2 = j.s2, t0 = j.t0, t1 = j.t1, t2 = j.t2;\n'
  '  const double r0 = j.r0, r1 = j.r1, r2 = j.r2, g0 = j.g0, g1 = j.g1, g2 = j.g2, b0 = j.b0, b1 = j.b1, b2 = j.b2;\n'
  '  int64_t drawn = 0, blended = 0, fastn = 0;\n'
  '  for (int y = j.miny; y <= j.maxy; ++y) {\n'
  '    if (parts > 1 && ((y >> 2) % parts) != part) continue;\n'
  '    const int64_t PY = 256 * static_cast<int64_t>(y) + 128;\n'
  '    int64_t xl = j.minx, xr = j.maxx, K[3];\n'
  '    for (int i = 0; i < 3; ++i) {\n'
  '      const int p = (i + 1) % 3;\n'
  '      K[i] = j.A[i] * (PY - j.Y[p]) + j.B[i] * j.X[p];   // w_i(x) = K_i - B_i * PX\n'
  '      const int64_t R = K[i] - (j.inc[i] ? 0 : 1);        // inside: w_i >= 0 on an owning edge, w_i >= 1 otherwise: B_i * PX '
  '<= R\n'
  '      if (j.B[i] > 0) xr = std::min(xr, floor_div(floor_div(R, j.B[i]) - 128, 256));\n'
  '      else if (j.B[i] < 0) xl = std::max(xl, ceil_div(ceil_div(-R, -j.B[i]) - 128, 256));\n'
  '      else if (R < 0) xr = xl - 1;\n'
  '    }\n'
  '    if (xl > xr) continue;\n'
  '    const int64_t PX0 = 256 * xl + 128;\n'
  '    int64_t w0 = K[0] - j.B[0] * PX0, w1 = K[1] - j.B[1] * PX0, w2 = K[2] - j.B[2] * PX0;\n'
  '    const int64_t d0 = 256 * j.B[0], d1 = 256 * j.B[1], d2 = 256 * j.B[2];\n'
  '    uint16_t *row = j.fb + static_cast<size_t>(y) * static_cast<size_t>(j.fbw);\n'
  '    const double(&drow)[4] = dith[y & 3];\n'
  '    for (int x = static_cast<int>(xl); x <= static_cast<int>(xr); ++x, w0 -= d0, w1 -= d1, w2 -= d2) {\n'
  '      const double a0 = static_cast<double>(w0) * kUnit, a1 = static_cast<double>(w1) * kUnit, a2 = static_cast<double>(w2) * '
  'kUnit;\n'
  '      if (approx) {\n'
  '        // the same pixel with the divisions replaced by products with the reciprocals; kept only when every rounding '
  'decision is\n'
  '        // farther from its boundary than the two computations can differ (bounds in the comment of fast_triangle_)\n'
  '        const double s = (a0 * s0 + a1 * s1 + a2 * s2) * inv_st, t = (a0 * t0 + a1 * t1 + a2 * t2) * inv_st;\n'
  '        const double u = s * twd, v = t * thd;\n'
  '        if (std::fabs(u) < kTexLim && std::fabs(v) < kTexLim) {\n'
  '          double r, g, bl, al = 255.0, fr_u, fr_v;\n'
  '          if (!linear) {\n'
  '            const int64_t iu0 = floor_i64(u), iv0 = floor_i64(v);\n'
  '            fr_u = u - iu0;\n'
  '            fr_v = v - iv0;\n'
  '            const uint8_t *tp = &td[(static_cast<size_t>(wrap_fast(iv0, th)) * tw + wrap_fast(iu0, tw)) * bpp];\n'
  '            r = tp[0]; g = tp[1]; bl = tp[2];\n'
  '            if (bpp == 4) al = tp[3];\n'
  '          } else {\n'
  '            const double fu = u - 0.5, fv = v - 0.5;\n'
  '            const int64_t i0 = floor_i64(fu), j0 = floor_i64(fv);\n'
  '            const double ax = fu - i0, ay = fv - j0;\n'
  '            fr_u = ax;\n'
  '            fr_v = ay;\n'
  '            const int x0 = wrap_fast(i0, tw), x1 = wrap_fast(i0 + 1, tw);\n'
  '            const size_t ry0 = static_cast<size_t>(wrap_fast(j0, th)) * tw, ry1 = static_cast<size_t>(wrap_fast(j0 + 1, th)) '
  '* tw;\n'
  '            const uint8_t *p00 = &td[(ry0 + x0) * bpp], *p01 = &td[(ry0 + x1) * bpp];\n'
  '            const uint8_t *p10 = &td[(ry1 + x0) * bpp], *p11 = &td[(ry1 + x1) * bpp];\n'
  '            const double w00 = (1 - ax) * (1 - ay), w01 = ax * (1 - ay), w10 = (1 - ax) * ay, w11 = ax * ay;\n'
  '            r = w00 * p00[0] + w01 * p01[0] + w10 * p10[0] + w11 * p11[0];\n'
  '            g = w00 * p00[1] + w01 * p01[1] + w10 * p10[1] + w11 * p11[1];\n'
  '            bl = w00 * p00[2] + w01 * p01[2] + w10 * p10[2] + w11 * p11[2];\n'
  '            if (bpp == 4) al = w00 * p00[3] + w01 * p01[3] + w10 * p10[3] + w11 * p11[3];\n'
  '          }\n'
  '          if (fr_u > kTexEps && fr_u < 1.0 - kTexEps && fr_v > kTexEps && fr_v < 1.0 - kTexEps) {\n'
  '            if (modulate) {\n'
  '              r *= white ? 1.0 : (a0 * r0 + a1 * r1 + a2 * r2) * inv_a;\n'
  '              g *= white ? 1.0 : (a0 * g0 + a1 * g1 + a2 * g2) * inv_a;\n'
  '              bl *= white ? 1.0 : (a0 * b0 + a1 * b1 + a2 * b2) * inv_a;\n'
  '            }\n'
  '            const uint16_t dsts = row[x];\n'
  '            if (blend) {\n'
  '              const double alpha = al * kInv255, beta = 1 - alpha;\n'
  '              r = r * alpha + tb.expand5[(dsts >> 10) & 31] * beta;\n'
  '              g = g * alpha + tb.expand5[(dsts >> 5) & 31] * beta;\n'
  '              bl = bl * alpha + tb.expand5[dsts & 31] * beta;\n'
  '            }\n'
  '            const double d = drow[x & 3];\n'
  '            const double qr = r * k31of255 + d, qg = g * k31of255 + d, qb = bl * k31of255 + d;\n'
  '            const int orr = floor_int(qr), og = floor_int(qg), ob = floor_int(qb);\n'
  '            const double fr = qr - orr, fg = qg - og, fb = qb - ob;\n'
  '            if (sloppy || (fr > kQuantEps && fr < 1.0 - kQuantEps && fg > kQuantEps && fg < 1.0 - kQuantEps && fb > kQuantEps '
  '&&\n'
  '                           fb < 1.0 - kQuantEps)) {\n'
  '              auto clamp5 = [](int o) { return o < 0 ? 0 : (o > 31 ? 31 : o); };\n'
  '              row[x] = static_cast<uint16_t>((clamp5(orr) << 10) | (clamp5(og) << 5) | clamp5(ob));\n'
  '              if (blend) ++blended;\n'
  '              ++drawn;\n'
  '              ++fastn;\n'
  '              continue;\n'
  '            }\n'
  '          }\n'
  '        }\n'
  '      }\n'
  "      // the exact branch: the general loop's expressions\n"
  '      const double s = (a0 * s0 + a1 * s1 + a2 * s2) / div_st;\n'
  '      const double t = (a0 * t0 + a1 * t1 + a2 * t2) / div_st;\n'
  '      const double u = s * twd, v = t * thd;\n'
  '      double r, g, bl, al = 255.0;\n'
  '      if (!linear) {\n'
  '        const int iu = wrap_fast(floor_i64(u), tw), iv = wrap_fast(floor_i64(v), th);\n'
  '        const uint8_t *tp = &td[(static_cast<size_t>(iv) * tw + iu) * bpp];\n'
  '        r = tp[0]; g = tp[1]; bl = tp[2];\n'
  '        if (bpp == 4) al = tp[3];\n'
  '      } else {\n'
  '        const double fu = u - 0.5, fv = v - 0.5;\n'
  '        const int64_t i0 = floor_i64(fu), j0 = floor_i64(fv);\n'
  '        const double ax = fu - i0, ay = fv - j0;\n'
  '        const int x0 = wrap_fast(i0, tw), x1 = wrap_fast(i0 + 1, tw);\n'
  '        const size_t ry0 = static_cast<size_t>(wrap_fast(j0, th)) * tw, ry1 = static_cast<size_t>(wrap_fast(j0 + 1, th)) * '
  'tw;\n'
  '        const uint8_t *p00 = &td[(ry0 + x0) * bpp], *p01 = &td[(ry0 + x1) * bpp];\n'
  '        const uint8_t *p10 = &td[(ry1 + x0) * bpp], *p11 = &td[(ry1 + x1) * bpp];\n'
  '        const double w00 = (1 - ax) * (1 - ay), w01 = ax * (1 - ay), w10 = (1 - ax) * ay, w11 = ax * ay;\n'
  '        double acc[4] = {0, 0, 0, 0};\n'
  '        for (int k = 0; k < bpp; ++k) acc[k] += w00 * p00[k];\n'
  '        for (int k = 0; k < bpp; ++k) acc[k] += w01 * p01[k];\n'
  '        for (int k = 0; k < bpp; ++k) acc[k] += w10 * p10[k];\n'
  '        for (int k = 0; k < bpp; ++k) acc[k] += w11 * p11[k];\n'
  '        r = acc[0]; g = acc[1]; bl = acc[2];\n'
  '        if (bpp == 4) al = acc[3];\n'
  '      }\n'
  '      double cr = (a0 * r0 + a1 * r1 + a2 * r2) / arA, cg = (a0 * g0 + a1 * g1 + a2 * g2) / arA;\n'
  '      double cb = (a0 * b0 + a1 * b1 + a2 * b2) / arA;\n'
  '      if (white) cr = cg = cb = 1.0;\n'
  '      if (modulate) { r *= cr; g *= cg; bl *= cb; }\n'
  '      uint16_t &dst = row[x];\n'
  '      double ro = r, go = g, bo = bl;\n'
  '      if (blend) {\n'
  '        const double alpha = al / 255.0;\n'
  '        const int dr = ((dst >> 10) & 31), dg = ((dst >> 5) & 31), db = dst & 31;\n'
  '        ro = r * alpha + tb.expand5[dr] * (1 - alpha);\n'
  '        go = g * alpha + tb.expand5[dg] * (1 - alpha);\n'
  '        bo = bl * alpha + tb.expand5[db] * (1 - alpha);\n'
  '        ++blended;\n'
  '      }\n'
  '      const double d = drow[x & 3];\n'
  '      dst = static_cast<uint16_t>((quantize_d(ro, d) << 10) | (quantize_d(go, d) << 5) | quantize_d(bo, d));\n'
  '      ++drawn;\n'
  '    }\n'
  '    if (j.wctl && parts > 1 && part == parts - 1) row[xl] ^= 1;   // negative control: a wrong pixel from the last worker '
  'only\n'
  '  }\n'
  '  c[0] += drawn;\n'
  '  c[1] += blended;\n'
  '  c[2] += fastn;\n'
  '}\n'
