 ('port/src/sim/terrain_state.cpp',
  'using TileP = Ptr<TerrainTile>;\nusing FaceP = Ptr<TerrainFace>;\n',
  '// ---- the object view (roadmap S3.10b, U-1388) ----\n'
  "// Every access of this file goes through VPtr, which has Ptr's interface and semantics. While an exported method runs\n"
  '// (terrain_dll_call), the Terrain object is resolved ONCE through Memory::at over its whole extent and the accesses that lie '
  'inside\n'
  '// it read and write the host bytes directly; any other access (an address outside the object, one that straddles its end, or '
  'no\n'
  '// view at all) goes to Memory as before and faults where it faulted. Equal results: Memory::at returns, for any sub-range of '
  'a range\n'
  '// it resolved in one piece, the same host bytes at the same offset (the state and the mappings never overlap, so the '
  'sub-range\n'
  "// resolves to the same mapping), and no mapping changes while a method runs. The object's mapping is writable (the view is "
  'made\n'
  '// with write = true; a read-only one gets no view).\n'
  'struct ObjView {\n'
  '  const Memory *mem = nullptr;\n'
  '  uint32_t base = 0, size = 0;\n'
  '  uint8_t *host = nullptr;\n'
  '};\n'
  'thread_local const ObjView *t_view = nullptr;\n'
  '\n'
  'template <class T> inline uint8_t *view_at(const Memory &m, uint32_t va) {\n'
  '  const ObjView *v = t_view;\n'
  '  if (v && v->mem == &m) {\n'
  '    const uint32_t rel = va - v->base;\n'
  '    if (rel < v->size && sizeof(T) <= v->size - rel) return v->host + rel;\n'
  '  }\n'
  '  return nullptr;\n'
  '}\n'
  'template <class T> inline T vload(const Memory &m, uint32_t va) {\n'
  '  if (const uint8_t *p = view_at<T>(m, va)) {\n'
  '    T x;\n'
  '    std::memcpy(&x, p, sizeof(T));\n'
  '    return x;\n'
  '  }\n'
  '  return m.load<T>(va);\n'
  '}\n'
  'template <class T> inline void vstore(const Memory &m, uint32_t va, const T &x) {\n'
  '  if (uint8_t *p = view_at<T>(m, va)) {\n'
  '    if constexpr (sizeof(T) == 1) {\n'
  '      if (g_negctl == 23) return;\n'
  '    }\n'
  '    std::memcpy(p, &x, sizeof(T));\n'
  '    return;\n'
  '  }\n'
  '  m.store<T>(va, x);\n'
  '}\n'
  '\n'
  "// Ptr's interface (the members this file uses) over the view. A VPtr made from an address looks the view up once and keeps "
  'the host\n'
  "// bytes from there to the view's end (`span`); a VPtr derived from it (field, +, at, byte) moves inside that span without "
  'another\n'
  "// lookup, and one that leaves the span, or was never in the view, takes vload / vstore (the view's own test, then Memory). "
  'So an\n'
  '// access reads and writes exactly the bytes vload / vstore would.\n'
  'template <class T> class VPtr {\n'
  ' public:\n'
  '  VPtr(const Memory &m, uint32_t va) : mem_(&m), va_(va) {\n'
  '    const ObjView *v = t_view;\n'
  '    if (v && v->mem == &m) {\n'
  '      const uint32_t rel = va - v->base;\n'
  '      if (rel < v->size) {\n'
  '        host_ = v->host + rel;\n'
  '        span_ = v->size - rel;\n'
  '      }\n'
  '    }\n'
  '  }\n'
  '  uint32_t va() const { return va_; }\n'
  '  VPtr operator+(int32_t n) const { return derive<T>(u32(n) * static_cast<uint32_t>(sizeof(T))); }\n'
  '  VPtr at(int32_t i) const { return *this + i; }\n'
  '  T get() const {\n'
  '    if (host_ && sizeof(T) <= span_) {\n'
  '      T x;\n'
  '      std::memcpy(&x, host_, sizeof(T));\n'
  '      return x;\n'
  '    }\n'
  '    return vload<T>(*mem_, va_);\n'
  '  }\n'
  '  void set(const T &v) const {\n'
  '    if (host_ && sizeof(T) <= span_) {\n'
  '      if constexpr (sizeof(T) == 1) {\n'
  '        if (g_negctl == 23) return;\n'
  '      }\n'
  '      std::memcpy(host_, &v, sizeof(T));\n'
  '      return;\n'
  '    }\n'
  '    vstore<T>(*mem_, va_, v);\n'
  '  }\n'
  '  template <class M, class S = T> VPtr<M> field(M S::*m) const {\n'
  '    static_assert(std::is_same<S, T>::value, "a member of another struct");\n'
  '    return derive<M>(detail::member_offset(m));\n'
  '  }\n'
  '  template <class M, size_t N, class S = T> VPtr<M> field(M (S::*m)[N]) const {\n'
  '    static_assert(std::is_same<S, T>::value, "a member of another struct");\n'
  '    return derive<M>(detail::member_offset(m));\n'
  '  }\n'
  '  VPtr<uint8_t> byte(int32_t off) const { return derive<uint8_t>(u32(off)); }\n'
  '  template <class U> VPtr<U> as_at(uint32_t off) const { return derive<U>(off); }   // (U *)((char *)p + off), wrapping\n'
  '  // the host bytes of [va, va + n) when all of them lie in the span, else nullptr (then use get / set): for reading or '
  'writing a\n'
  '  // whole record in place, the same bytes get / set would touch\n'
  '  uint8_t *host(uint32_t n) const { return host_ && n <= span_ ? host_ : nullptr; }\n'
  '\n'
  ' private:\n'
  '  template <class U> friend class VPtr;\n'
  '  VPtr(const Memory &m, uint32_t va, uint8_t *host, uint32_t span) : mem_(&m), va_(va), host_(host), span_(span) {}\n'
  '  // the address va + off (wrapping); its host bytes when off stays inside the span\n'
  '  template <class U> VPtr<U> derive(uint32_t off) const {\n'
  '    if (host_ && off < span_) return VPtr<U>(*mem_, va_ + off, host_ + off, span_ - off);\n'
  '    return VPtr<U>(*mem_, va_ + off, nullptr, 0);\n'
  '  }\n'
  '  const Memory *mem_;\n'
  '  uint32_t va_;\n'
  '  uint8_t *host_ = nullptr;\n'
  '  uint32_t span_ = 0;\n'
  '};\n'
  '\n'
  '// Installs the view of the object at `base` for the current scope (none when `base` is 0 or Memory cannot resolve the whole '
  'object\n'
  "// writable: then every access takes Memory's path).\n"
  'class ViewScope {\n'
  ' public:\n'
  '  ViewScope(const Memory &m, uint32_t base) : prev_(t_view) {\n'
  '    if (base == 0) return;\n'
  '    try {\n'
  '      v_.host = m.at(base, kTerrainObjectSize, true);\n'
  '    } catch (const Fault &) {\n'
  '      return;\n'
  '    }\n'
  '    v_.mem = &m;\n'
  '    v_.base = base;\n'
  '    v_.size = kTerrainObjectSize;\n'
  '    t_view = &v_;\n'
  '  }\n'
  '  ~ViewScope() { t_view = prev_; }\n'
  '  ViewScope(const ViewScope &) = delete;\n'
  '  ViewScope &operator=(const ViewScope &) = delete;\n'
  '\n'
  ' private:\n'
  '  ObjView v_;\n'
  '  const ObjView *prev_;\n'
  '};\n'
  '\n'
  'using TileP = VPtr<TerrainTile>;\n'
  'using FaceP = VPtr<TerrainFace>;\n'),
