  '    std::string line = std::to_string(r.seq) + " 0 0 " + r.name + " " + hex(r.self);\n'
  '    for (size_t i = 0; i < 5; ++i) line += " " + (i < r.k ? hex(r.a[i]) : std::string("-"));\n'
  '    line += " " + hex(r.ret);\n'
  '    if (r.has_tbl) {\n'
  '      line += " tbl=";\n'
  '      for (size_t i = 0; i < r.tbl.size(); ++i) line += (i ? "," : "") + std::to_string(r.tbl[i]);\n'
  '    }\n'
  '    if (r.has_var) line += " var=" + std::to_string(r.var);\n'
  '    log_.push_back(std::move(line));\n'
  '  }\n'
  '  recs_.clear();\n'
  '  return log_;\n'
  '}\n'
